mapper.select:
SELECT 
FROM chat_attachment
WHERE tenant_id=#{tenantId} AND user_id=#{userId} AND attachment_id=#{attachmentId}

mapper.update:
UPDATE chat_attachment
SET session_id=#{sessionId},turn_id=#{turnId},bound_at=#{boundAt}
WHERE tenant_id=#{tenantId} AND user_id=#{userId} AND attachment_id=#{attachmentId}
  AND parse_status='ready'
  AND (
    (session_id IS NULL AND turn_id IS NULL)
    OR (session_id=#{sessionId} AND turn_id=#{turnId})
  )

mapper.delete:
DELETE FROM chat_attachment
WHERE tenant_id=#{tenantId} AND user_id=#{userId} AND attachment_id=#{attachmentId}
  AND session_id IS NULL AND turn_id IS NULL
